class Solution {
public:
    int findShortestSubArray(vector<int>& nums) {
        unordered_map<int, int> freq, first;
        int degree = 0, answer = nums.size();
        for (int i = 0; i < (int)nums.size(); ++i) {
            int x = nums[i];
            if (!freq.count(x)) first[x] = i;
            int count = ++freq[x];
            if (count > degree) {
                degree = count;
                answer = i - first[x] + 1;
            } else if (count == degree) {
                answer = min(answer, i - first[x] + 1);
            }
        }
        return answer;
    }
};
